const body = $input.first().json.body;
const entries = body.entries || [];
const feed = body.feed || {};

const results = [];

for (const entry of entries) {
  const title = (entry.title || 'Untitled').substring(0, 256);
  const url = entry.url || '';
  const publishedAt = entry.published_at || '';
  const author = entry.author || '';
  const feedTitle = feed.title || '';

  let description = entry.summary || '';
  if (!description && entry.content) {
    description = entry.content.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }
  description = description.substring(0, 400);

  const discordPayload = {
    embeds: [{
      type: 'rich',
      title: title,
      url: url,
      description: description,
      timestamp: publishedAt,
      footer: {
        text: `Feed: ${feedTitle}`.substring(0, 2048)
      },
      fields: []
    }],
    allowed_mentions: { parse: [] }
  };

  if (author) {
    discordPayload.embeds[0].fields.push({
      name: 'Author',
      value: author.substring(0, 1024),
      inline: true
    });
  }

  results.push({ json: discordPayload });
}

return results;
